class ThreadSafeBuffer {
private:
    std::mutex mtx;
    std::vector<int> data;
    bool is_initialized;

public:
    ThreadSafeBuffer() : is_initialized(false) {}

    void initialize(size_t size) {
        std::lock_guard<std::mutex> lock(mtx);
        if (!is_initialized) {
            data.resize(size, 0);
            is_initialized = true;
        }
    }

    // 安全版本：使用 RAII 锁保证线程安全，且通过 is_initialized 标志防止未初始化访问
    int getValue(size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (!is_initialized) {
            return -1;  // 防御：未初始化时返回错误码，避免空指针/未定义行为
        }
        if (index >= data.size()) {
            return -1;  // 防御：边界检查
        }
        return data[index];
    }

    void setValue(size_t index, int value) {
        std::lock_guard<std::mutex> lock(mtx);
        if (!is_initialized) {
            return;  // 防御：未初始化时静默失败
        }
        if (index >= data.size()) {
            return;  // 防御：边界检查
        }
        data[index] = value;
    }
};

// 模拟工作线程
void worker(ThreadSafeBuffer& buffer, int thread_id) {
    for (int i = 0; i < 100; ++i) {
        buffer.setValue(i % 10, thread_id * 100 + i);
        int val = buffer.getValue(i % 10);
        if (val == -1) {
            std::cout << "Thread " << thread_id << ": buffer not ready or out of bounds\n";
        }
    }
}

int main() {
    ThreadSafeBuffer buffer;
    buffer.initialize(10);  // 初始化在启动线程之前完成

    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back(worker, std::ref(buffer), i);
    }

    for (auto& t : threads) {
        t.join();
    }

    std::cout << "All threads completed safely\n";
    return 0;
}

