#include <fstream>
#include <string>
#include <vector>
#include <memory>
#include <iostream>

class FileProcessor {
private:
    std::ifstream* stream_;
    bool is_open_;

public:
    FileProcessor() : stream_(nullptr), is_open_(false) {}

    ~FileProcessor() {
        close();
    }

    bool open(const std::string& path) {
        close(); // 确保之前资源已释放
        stream_ = new std::ifstream(path);
        is_open_ = stream_->is_open();
        if (!is_open_) {
            delete stream_;
            stream_ = nullptr;
        }
        return is_open_;
    }

    void close() {
        if (stream_ != nullptr) {
            if (is_open_) {
                stream_->close();
            }
            delete stream_;
            stream_ = nullptr;
            is_open_ = false;
        }
    }

    std::string readLine() {
        if (!is_open_ || stream_ == nullptr) {
            return "";
        }
        std::string line;
        std::getline(*stream_, line);
        return line;
    }
};

bool processFile(const std::string& filepath, std::vector<std::string>& output) {
    FileProcessor processor;
    if (!processor.open(filepath)) {
        std::cerr << "Failed to open: " << filepath << std::endl;
        return false;
    }

    std::string line;
    while (!(line = processor.readLine()).empty()) {
        output.push_back(line);
        if (output.size() > 10000) {
            std::cerr << "File too large" << std::endl;
            return false;
        }
    }
    return true;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <file>" << std::endl;
        return 1;
    }

    std::vector<std::string> lines;
    if (processFile(argv[1], lines)) {
        std::cout << "Processed " << lines.size() << " lines" << std::endl;
    }
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_PACKET_SIZE 1024
#define HEADER_SIZE 8

typedef struct {
    uint8_t *data;
    size_t length;
} Packet;

int parse_packet(const uint8_t *raw_data, size_t raw_len, Packet *out) {
    if (raw_data == NULL || out == NULL) {
        return -1;
    }

    if (raw_len < HEADER_SIZE) {
        return -1;
    }

    // Extract payload length from header (bytes 4-7, big-endian)
    uint32_t payload_len = 0;
    for (int i = 0; i < 4; i++) {
        payload_len = (payload_len << 8) | raw_data[4 + i];
    }

    // Validate payload length against actual remaining data
    if (payload_len > raw_len - HEADER_SIZE) {
        return -1;
    }

    // Allocate exactly payload_len bytes
    uint8_t *payload = (uint8_t *)malloc(payload_len);
    if (payload == NULL) {
        return -1;
    }

    // Copy payload with verified length
    memcpy(payload, raw_data + HEADER_SIZE, payload_len);

    out->data = payload;
    out->length = payload_len;
    return 0;
}

void free_packet(Packet *pkt) {
    if (pkt != NULL) {
        free(pkt->data);
        pkt->data = NULL;
        pkt->length = 0;
    }
}

int main() {
    uint8_t buffer[MAX_PACKET_SIZE];
    size_t received = 0;

    // Simulate receiving a network packet
    received = fread(buffer, 1, sizeof(buffer), stdin);
    if (received == 0) {
        return 1;
    }

    Packet pkt = {0};
    if (parse_packet(buffer, received, &pkt) == 0) {
        printf("Parsed %zu bytes of payload\n", pkt.length);
        free_packet(&pkt);
    }
    return 0;
}

// app/views.py - Django 视图处理用户资料更新
from django.shortcuts import render, redirect
from django.contrib.auth.decorators import login_required
from django.views.decorators.http import require_POST
from django.views.decorators.csrf import csrf_protect
from django.core.exceptions import PermissionDenied
from .models import UserProfile
from .forms import ProfileUpdateForm

@login_required
@require_POST
@csrf_protect
def update_profile(request):
    """
    处理用户资料更新请求，仅接受 POST 方法。
    使用 Django 内置 CSRF 中间件和 csrf_protect 装饰器双重防护。
    """
    # 获取当前登录用户（由 login_required 保证）
    user = request.user

    # 绑定表单数据，进行字段级验证
    form = ProfileUpdateForm(request.POST, instance=user.profile)

    if not form.is_valid():
        # 验证失败，返回错误信息（不涉及敏感数据）
        return render(request, 'profile/edit.html', {'form': form, 'error': '输入数据不合法'})

    # 保存数据前再次确认用户身份（防止会话固定攻击）
    if user.id != request.session.get('_auth_user_id'):
        raise PermissionDenied("会话异常，请重新登录")

    # 保存更新后的资料
    form.save()

    # 重定向到个人主页（PRG 模式防止重复提交）
    return redirect('profile:view', user_id=user.id)
